return function(a,b,c)local d,e,f={},{},{}local g=0;for h,i in pairs(c)do local j=assert(b:get(h),"Could not find package '"..h.."' in cache")if i then local k,l={},{}l["install:"..h]=true;for m,n in ipairs(j.preDepends)do if c[n.package]==true then k["configure:"..n.package]=true end end;for m,n in ipairs(j.depends)do if c[n.package]==true then l["configure:"..n.package]=true end end;for m,n in ipairs(j.conflicts)do if c[n.package]==false then k["remove:"..n.package]=true end end;for m,n in ipairs(j.breaks)do if c[n.package]==false then l["deconfigure:"..n.package]=true end end;e["install:"..h]=k;e["configure:"..h]=l;if not next(k)then d[#d+1]="install:"..h end else local o,p={},{}p["deconfigure:"..h]=true;for m,n in ipairs(j.preDepended)do if c[n.package]==false then o["remove:"..n.package]=true end end;for m,n in ipairs(j.depended)do if c[n.package]==false then o["deconfigure:"..n.package]=true end end;e["deconfigure:"..h]=o;e["remove:"..h]=p;if not next(o)then d[#d+1]="deconfigure:"..h end end;g=g+2 end;while#d>0 do table.sort(d,function(q,r)local s,t=q:match"([^:]+):(.+)"local u,v=r:match"([^:]+):(.+)"if s=="install"and u=="configure"then return true elseif s=="configure"and u=="install"then return false elseif s=="remove"and u=="deconfigure"then return false elseif s=="deconfigure"and u=="remove"then return true else return t<v end end)local w=table.remove(d,1)f[#f+1]=w;for h,i in pairs(e)do if i[w]then i[w]=nil;if not next(i)then d[#d+1]=h end end end end;if#f<g then return nil,"Cycle in dependency graph"end;return f end
